            g.beginPath();
            g.ellipse(2, 4, 9, 8, 0, 0, U.TAU);
            g.fill();
            g.rotate(e.facing);
            const L = lunge(e);
            g.translate(0, bob * 0.5);
            // thruster nozzles
            g.fillStyle = '#2b3036';
            g.fillRect(-12, -4.5, 5, 3);
            g.fillRect(-12, 1.5, 5, 3);
            // stubby arms and hands with knives
            for (let i = 0; i < 2; i++) {
              const s = i === 0 ? -1 : 1;
              const ph = Math.sin(e.t * 10 + (i === 0 ? 0 : Math.PI));
              const hx = 6 + L + ph * 1.2;
              const hy = s * 9.5;
              g.fillStyle = '#4a525a';
              g.fillRect(2, s > 0 ? 5 : -8, 4 + L * 0.5, 3);
              g.fillStyle = '#5a636b';
              g.beginPath();
              g.arc(hx, hy, 2.8, 0, U.TAU);
              g.fill();
              g.fillStyle = '#2a2622';
              g.fillRect(hx, hy - 1, 3, 2);
              g.fillStyle = '#dfe5ea';
              g.beginPath();
              g.moveTo(hx + 3, hy - 1.4);
              g.lineTo(hx + 10, hy - 0.2);
              g.lineTo(hx + 12, hy + 0.3);
              g.lineTo(hx + 3, hy + 1.4);
              g.closePath();
              g.fill();
              g.strokeStyle = '#8a949c';
              g.lineWidth = 0.6;
              g.beginPath();
              g.moveTo(hx + 3, hy + 0.5);
              g.lineTo(hx + 11, hy + 0.2);
              g.stroke();
            }
