            const attacking = Math.abs(lunge(e)) > 0.6;
            const col = attacking ? '#ff4a3a' : '#7fffd4';
            const msgs = [':)', 'HI', '1/40', 'OOPS', 'BYE', 'HELLO'];
            const phase = e.t * 0.7 + id * 0.37;
            const idx = Math.abs(Math.floor(phase) + id * 7) % msgs.length;
            const frac = phase - Math.floor(phase);
            g.save();
            g.rotate(e.facing);
            // thruster flames
            const fl = 2.5 + Math.sin(e.t * 40 + id) * 1;
            g.fillStyle = 'rgba(120,200,255,0.8)';
            g.beginPath();
            g.ellipse(-12 - fl * 0.5, -3, fl, 1.4, 0, 0, U.TAU);
            g.ellipse(-12 - fl * 0.5, 3, fl, 1.4, 0, 0, U.TAU);
            g.fill();
            // visor screen
            g.globalAlpha = 0.85;
            g.fillStyle = col;
            g.beginPath();
            g.ellipse(4.5, 0, 3.4, 5, 0, 0, U.TAU);
            g.fill();
            g.globalAlpha = 1;
            g.fillStyle = '#05100c';
            g.save();
            g.translate(4.5, 0);
            g.rotate(Math.PI / 2);
            g.font = 'bold 4px monospace';
            g.textAlign = 'center';
            g.textBaseline = 'middle';
            if (attacking) {
              g.fillText('STAB', 0, 0);
            } else if (frac > 0.9) {
              g.fillRect(-4, -1.5, 8, 0.8);
              g.fillRect(-4, 0.5, 8, 0.8);
            } else {
              g.fillText(msgs[idx], 0, 0);
            }
            g.restore();
            // knife glints
            g.fillStyle = 'rgba(255,255,255,0.7)';
            g.fillRect(17 + lunge(e), -9.7, 1.5, 0.8);
            g.fillRect(17 + lunge(e), 9, 1.5, 0.8);
            g.restore();
